    /**
     * Tests getting all Deals.
     *
     * @return    Collection
     */
    public List<Deal> testGetAll() throws Throwable {
    LOGGER.info( "DealTest:testGetAll() - Retrieving Collection of Deals:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Deal : " );
    List<Deal> collection  = null;

    try {
        // call the static get method on the DealService
        collection = service.getAllDeal();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Deal currEntity  = null;
            Iterator<Deal> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDealId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

